-- Public, indexable pages (Phase 7): localized slugs with retained history.
--
-- The route scope is the entity type (`/song/…` = composition, `/artist/…`, `/recording/…`).
-- A slug is unique per (scope, language), so the same words can name different entities in
-- different languages but never two in one. Exactly one slug per (entity, language) is current;
-- every earlier slug stays forever and redirects to the current one. Rows are never deleted.
-- Slugs are generated by the worker (see `seo::sync`) from the localized display title.

CREATE TABLE localized_slugs (
    id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    entity_type text        NOT NULL CHECK (entity_type IN ('composition', 'artist', 'recording')),
    entity_id   uuid        NOT NULL,
    language_id uuid        NOT NULL REFERENCES languages (id),
    slug        text        NOT NULL CHECK (length(slug) BETWEEN 1 AND 200 AND slug = normalize(slug, NFC)),
    is_current  boolean     NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT localized_slugs_scope_key UNIQUE (entity_type, language_id, slug)
);
CREATE UNIQUE INDEX localized_slugs_current_key ON localized_slugs (entity_type, entity_id, language_id)
    WHERE is_current;
CREATE INDEX localized_slugs_entity_idx ON localized_slugs (entity_type, entity_id);

-- History is append-only except for the current flag.
CREATE FUNCTION localized_slugs_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' OR TG_OP = 'TRUNCATE' THEN
        RAISE EXCEPTION 'localized_slugs history is retained' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF (NEW.entity_type, NEW.entity_id, NEW.language_id, NEW.slug, NEW.created_at)
       IS DISTINCT FROM (OLD.entity_type, OLD.entity_id, OLD.language_id, OLD.slug, OLD.created_at) THEN
        RAISE EXCEPTION 'a slug cannot be edited, only retired' USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER localized_slugs_no_delete BEFORE DELETE ON localized_slugs
    FOR EACH ROW EXECUTE FUNCTION localized_slugs_guard();
CREATE TRIGGER localized_slugs_no_edit BEFORE UPDATE ON localized_slugs
    FOR EACH ROW EXECUTE FUNCTION localized_slugs_guard();
CREATE TRIGGER localized_slugs_no_truncate BEFORE TRUNCATE ON localized_slugs
    FOR EACH STATEMENT EXECUTE FUNCTION localized_slugs_guard();

-- A page exists only for published content: a song or recording with a published lyric, or an artist
-- credited on one. The same rule serves page reads, slug creation and the sitemap.
CREATE FUNCTION seo_is_public(t text, eid uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
    SELECT CASE t
        WHEN 'recording' THEN EXISTS (
            SELECT 1 FROM contributions WHERE recording_id = eid AND published_revision_id IS NOT NULL)
        WHEN 'composition' THEN EXISTS (
            SELECT 1 FROM contributions c JOIN recordings r ON r.id = c.recording_id
            WHERE r.composition_id = eid AND c.published_revision_id IS NOT NULL)
        WHEN 'artist' THEN EXISTS (
            SELECT 1 FROM contributions c JOIN recordings r ON r.id = c.recording_id
            WHERE c.published_revision_id IS NOT NULL AND EXISTS (
                SELECT 1 FROM credits x WHERE x.artist_id = eid AND (x.recording_id = r.id OR x.composition_id = r.composition_id)))
        ELSE false
    END
$$;

-- Everything an operator may tune without a deploy.
INSERT INTO settings (key, value) VALUES ('seo', '{
  "locales": ["en", "ar"],
  "default_locale": "en",
  "slug": {"preserve_native_script": true, "ascii_fold_latin": true, "max_length": 80, "separator": "-"},
  "sitemap_page_size": 5000
}');

-- Pages that exist already get slugs through the same event the search indexer uses.
INSERT INTO outbox (topic, aggregate_type, aggregate_id, payload)
SELECT 'search.reindex', t, id, '{}' FROM (
    SELECT 'composition' AS t, id FROM compositions UNION ALL
    SELECT 'recording', id FROM recordings UNION ALL
    SELECT 'artist', id FROM artists) x
ON CONFLICT (aggregate_type, aggregate_id)
    WHERE topic = 'search.reindex' AND processed_at IS NULL AND attempts = 0 DO NOTHING;

-- A changed default language changes which locales have content.
CREATE TRIGGER compositions_default_language_docs AFTER UPDATE OF default_language_id ON compositions
    FOR EACH ROW EXECUTE FUNCTION search_documents_entity_trigger('composition');
CREATE TRIGGER recordings_default_language_docs AFTER UPDATE OF default_language_id ON recordings
    FOR EACH ROW EXECUTE FUNCTION search_documents_entity_trigger('recording');
CREATE TRIGGER artists_default_language_docs AFTER UPDATE OF default_language_id ON artists
    FOR EACH ROW EXECUTE FUNCTION search_documents_entity_trigger('artist');
